# owner: platform
"""Lay students out in rows, one text line per row."""

from operator import attrgetter
from typing import Iterable, List

from rosterkit.models import Student


# ---
def seat_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per seating row, by last name."""
    roster = list(students)
    check_seating(roster, seats_per_row)
    ordered = sorted(roster, key=attrgetter("last_name"))
    return row_lines(ordered, seats_per_row)


# ---
def check_seating(
    roster: List[Student], seats: int
) -> None:
    """Reject a bad seat count or an empty roster."""
    if seats <= 0:
        raise ValueError(f"bad seat count: {seats}")
    if not roster:
        raise ValueError("no students to seat")


# ---
def row_lines(
    ordered: List[Student], seats: int
) -> List[str]:
    starts = range(0, len(ordered), seats)
    return [
        row_text(number, ordered[begin:begin + seats])
        for number, begin in enumerate(starts, start=1)
    ]


# ---
def row_text(number: int, seated: List[Student]) -> str:
    """Label one row with its names separated by bars."""
    names = " | ".join(item.display_name for item in seated)
    return f"Row {number}: {names}"
